"""Generated branch functions return a declared label on every path (generated by adk_v2/6.0.0)."""

import pytest

from retail_kyc_onboarding._engine.engine.evaluator import build_route_function
from retail_kyc_onboarding.workflow import WORKFLOW

CONDITIONS = sorted(((cid, c) for u in WORKFLOW.all_units() for cid, c in u.conditions.items()), key=lambda x: x[0])


@pytest.mark.skipif(not CONDITIONS, reason="this export has no branch conditions")
@pytest.mark.parametrize("condition", [c for _, c in CONDITIONS], ids=[cid for cid, _ in CONDITIONS])
@pytest.mark.parametrize("is_error", [False, True])
def test_the_condition_returns_a_declared_label(condition, is_error: bool):
    """Each condition declares its labels and returns one of them for a success and for an error result."""
    assert condition.labels, "a condition must declare the labels it can return"
    route = build_route_function(condition.source)
    assert route(result=None, is_error=is_error, workflow_variables={}) in condition.labels
